             <label for="phone">Phone number</label>
             <input
               id="phone"
               name="phone"
               type="tel"
               inputmode="tel"
               autocomplete="tel"
               placeholder="+1 555 123 4567"
               aria-describedby="phone-hint phone-error"
             />
